// Auto-generated for the Unit Board — 學測易混淆字 熟字僻義 (tools/confusables/build.py)
window.FC_DASHBOARD_UNITS = [{"unit":1,"theme":"appeal；arrest；bore…","cards":[{"w":"appeal","p":"v./n.","d":"to attract or interest; to ask a higher court to change a decision","c":"常見：呼籲；懇求／進階：吸引；上訴","s":"The game's simple design appeals to people of all ages.","t":"這款遊戲的簡單設計吸引各年齡層的人。"},{"w":"arrest","p":"v./n.","d":"to stop something from continuing; to catch attention","c":"常見：逮捕／進階：遏止；吸引（注意）；（心跳）停止","s":"The new law helped arrest the decline of the local fishing industry.","t":"新法有助遏止當地漁業的衰退。"},{"w":"bore","p":"v.","d":"past tense of bear: carried, gave birth to, accepted","c":"常見：使厭煩／進階：承受；生育（bear 的過去式）","s":"She bore the pain bravely and finished the race.","t":"她勇敢地忍住疼痛跑完比賽。"},{"w":"cast","p":"n.","d":"all the actors in a film or play; a hard cover for a broken bone","c":"常見：投擲；投下／進階：演員陣容；石膏","s":"The whole cast of the movie came to the opening night.","t":"電影的全體演員都出席了首映夜。"},{"w":"champion","p":"v.","d":"to support and fight for a cause","c":"常見：冠軍／進階：擁護；捍衛","s":"The young lawyer champions the rights of migrant workers.","t":"這位年輕律師捍衛移工的權益。"},{"w":"clip","p":"n./v.","d":"a short part of a film; to cut something","c":"常見：夾子；迴紋針／進階：影片片段；修剪","s":"The teacher showed us a short clip from the news before the discussion.","t":"討論前老師給我們看了一段新聞片段。"},{"w":"coach","p":"n.","d":"a large comfortable bus for long trips; economy seats on a plane","c":"常見：教練；指導／進階：長途巴士；經濟艙","s":"We traveled from London to Oxford by coach because it was cheaper than the train.","t":"我們從倫敦搭長途巴士到牛津，因為比火車便宜。"},{"w":"column","p":"n.","d":"a regular article in a newspaper or magazine; a vertical row","c":"常見：圓柱；柱子／進階：專欄；（直）欄","s":"She writes a weekly column about food and travel.","t":"她每週撰寫一篇美食旅遊專欄。"},{"w":"crane","p":"n./v.","d":"a tall machine for lifting heavy things; to stretch your neck to see","c":"常見：鶴／進階：起重機；伸長脖子","s":"Workers used a crane to lift the steel beams to the top of the building.","t":"工人用起重機把鋼樑吊到大樓頂端。"},{"w":"credit","p":"n.","d":"praise for doing something; a unit of study","c":"常見：信用；賒帳／進階：功勞；讚揚；學分","s":"The whole team deserves credit for this success, not just me.","t":"這次成功全隊都有功勞，不只是我。"}]},{"unit":2,"theme":"deposit；engage；fortune…","cards":[{"w":"deposit","p":"n.","d":"money paid first as a promise; a layer of material left by water","c":"常見：存款；存入／進階：押金；訂金；沉積物","s":"We paid a deposit of two months' rent when we moved in.","t":"我們搬進去時付了兩個月租金的押金。"},{"w":"engage","p":"v.","d":"to take part in; to attract and keep interest","c":"常見：訂婚／進階：參與；吸引","s":"Good teachers find ways to engage students in discussion.","t":"好老師會想辦法吸引學生投入討論。"},{"w":"fortune","p":"n.","d":"a very large amount of money","c":"常見：運氣；命運／進階：財富；鉅款","s":"He made a fortune by selling his app to a big company.","t":"他把應用程式賣給大公司，賺了一大筆錢。"},{"w":"harbor","p":"v.","d":"to keep a feeling or thought for a long time; to hide someone","c":"常見：港口／進階：懷有（情感）；窩藏","s":"She still harbors hope that her lost cat will come home one day.","t":"她仍懷抱希望，相信走失的貓有一天會回家。"},{"w":"hatch","p":"v./n.","d":"to make a secret plan; a door in a ship or plane","c":"常見：孵化／進階：策劃；艙口","s":"The students hatched a plan to surprise their teacher on her birthday.","t":"學生們策劃在老師生日時給她驚喜。"},{"w":"observe","p":"v.","d":"to obey a rule or law; to celebrate a holiday","c":"常見：觀察／進階：遵守；慶祝（節日）","s":"All drivers must observe the speed limit.","t":"所有駕駛人都必須遵守速限。"},{"w":"odd","p":"adj.","d":"(of numbers) not able to be divided by two; occasional","c":"常見：奇怪的／進階：奇數的；零星的","s":"Students with odd numbers sit on the left side of the room.","t":"座號是奇數的學生坐教室左邊。"},{"w":"palm","p":"n.","d":"a tall tropical tree with large leaves","c":"常見：手掌／進階：棕櫚樹","s":"Tall palm trees line the road along the beach.","t":"海邊道路兩旁種滿高大的棕櫚樹。"},{"w":"pitch","p":"n./v.","d":"how high or low a sound is; a talk to sell something; to set up a tent","c":"常見：投（球）／進階：音高；推銷；搭（帳篷）","s":"We pitched our tent near the lake before it got dark.","t":"我們在天黑前在湖邊搭好帳篷。"},{"w":"plastic","p":"adj.","d":"easily shaped or changed","c":"常見：塑膠（的）／進階：可塑的；整形的","s":"Young children's brains are very plastic, so they learn languages quickly.","t":"幼兒大腦可塑性很高，所以學語言很快。"}]},{"unit":3,"theme":"relief；sack；scale…","cards":[{"w":"relief","p":"n.","d":"help such as food and money for people in need","c":"常見：寬慰；放心；緩解／進階：救濟；救援物資","s":"Many countries sent relief to the flood victims.","t":"許多國家送救援物資給水災災民。"},{"w":"sack","p":"v./n.","d":"to fire someone from a job","c":"常見：麻袋；大袋／進階：開除；解僱","s":"He was sacked for being late to work too many times.","t":"他因上班遲到太多次而被開除。"},{"w":"scale","p":"n.","d":"a machine for weighing; one of the small plates on a fish","c":"常見：規模；等級；比例尺／進階：磅秤；鱗片","s":"Put the bag of apples on the scale to see how much it weighs.","t":"把那袋蘋果放到磅秤上看看多重。"},{"w":"seal","p":"v./n.","d":"to close something tightly; an official mark","c":"常見：海豹／進階：密封；封住；印章","s":"Seal the box with tape before you mail it.","t":"寄出前用膠帶把箱子封好。"},{"w":"tender","p":"adj.","d":"(of meat) soft and easy to cut; painful when touched","c":"常見：溫柔的／進階：嫩的；（一碰就）痛的","s":"The beef was so tender that it fell apart in my mouth.","t":"牛肉嫩到在嘴裡化開。"},{"w":"trunk","p":"n.","d":"the space at the back of a car; an elephant's long nose","c":"常見：樹幹／進階：後車廂；象鼻","s":"Put the suitcases in the trunk before we leave.","t":"出發前把行李箱放進後車廂。"},{"w":"volume","p":"n.","d":"one book in a set; the amount of something","c":"常見：音量／進階：冊；卷；量","s":"The volume of traffic increases during holidays.","t":"假日期間交通量增加。"},{"w":"wage","p":"v.","d":"to carry on a war or a campaign","c":"常見：工資／進階：發動；進行（戰爭、運動）","s":"The city is waging a war against illegal parking.","t":"市政府正全面打擊違規停車。"},{"w":"abstract","p":"n.","d":"a short summary of a long article","c":"常見：抽象的／進階：摘要","s":"Read the abstract first to see if the article is useful.","t":"先讀摘要，看看這篇文章是否有用。"},{"w":"apparent","p":"adj.","d":"seeming to be true but possibly not","c":"常見：明顯的／進階：表面上的；看似的","s":"His apparent calm hid how worried he really was.","t":"他表面上的冷靜掩蓋了他其實有多擔心。"}]},{"unit":4,"theme":"bargain；bond；cabinet…","cards":[{"w":"bargain","p":"v./n.","d":"to discuss the price or terms; an agreement","c":"常見：便宜貨；划算的東西／進階：討價還價；協議","s":"Tourists often bargain with sellers at the night market.","t":"觀光客常在夜市跟攤販殺價。"},{"w":"bond","p":"n.","d":"a document from a government or company promising to pay back money","c":"常見：聯繫；情誼；建立感情／進階：債券","s":"My parents put some of their savings into government bonds.","t":"我爸媽把部分存款投資在政府公債。"},{"w":"cabinet","p":"n.","d":"the group of top ministers in a government","c":"常見：櫥櫃／進階：內閣","s":"The premier announced several changes to the cabinet.","t":"行政院長宣布內閣改組。"},{"w":"capacity","p":"n.","d":"ability; a job or position","c":"常見：容量；容納能力／進階：能力；身分；職位","s":"She spoke at the meeting in her capacity as class leader.","t":"她以班長身分在會議上發言。"},{"w":"content","p":"adj.","d":"happy and satisfied","c":"常見：內容／進階：滿足的；滿意的","s":"My grandmother is content with a quiet life in the countryside.","t":"我奶奶滿足於鄉下平靜的生活。"},{"w":"counter","p":"v.","d":"to say something against; to act against","c":"常見：櫃檯；流理台／進階：反駁；對抗","s":"The company quickly countered the rumors with a clear statement.","t":"公司迅速發表聲明反駁謠言。"},{"w":"critical","p":"adj.","d":"extremely important; very serious and dangerous","c":"常見：批評的；挑剔的／進階：關鍵的；危急的","s":"The next two days are critical for the patient's recovery.","t":"接下來兩天是病人康復的關鍵期。"},{"w":"discipline","p":"n.","d":"a subject of study","c":"常見：紀律；管教／進階：學科；領域","s":"The course combines several disciplines, such as biology and chemistry.","t":"這門課結合生物、化學等多個學科。"},{"w":"dismiss","p":"v.","d":"to refuse to consider something seriously","c":"常見：解散；開除／進階：不予考慮；駁回","s":"The manager dismissed my idea without even listening to it.","t":"經理連聽都沒聽就否決了我的點子。"},{"w":"drill","p":"n./v.","d":"a practice exercise; to train by repeating","c":"常見：鑽子；鑽孔／進階：演練；反覆練習","s":"We have an earthquake drill at school every September.","t":"我們學校每年九月有地震演習。"}]},{"unit":5,"theme":"entertain；exhaust；frame…","cards":[{"w":"entertain","p":"v.","d":"to consider an idea; to invite guests and give them food","c":"常見：娛樂；使快樂／進階：考慮（想法）；招待","s":"The company refused to entertain any suggestions from new workers.","t":"公司拒絕考慮新進員工的任何建議。"},{"w":"exhaust","p":"v./n.","d":"to use up completely; waste gas from a car","c":"常見：使筋疲力盡／進階：耗盡；廢氣","s":"We exhausted all our savings on the trip.","t":"我們這趟旅行花光了所有積蓄。"},{"w":"frame","p":"v.","d":"to make an innocent person seem guilty","c":"常見：框；框架；裝框／進階：陷害；栽贓","s":"The man claimed he had been framed by his business partner.","t":"這名男子聲稱遭生意夥伴陷害。"},{"w":"grave","p":"adj.","d":"very serious and worrying","c":"常見：墳墓／進階：嚴重的；嚴肅的","s":"Driving after drinking is a grave mistake that can cost lives.","t":"酒駕是可能奪人性命的嚴重錯誤。"},{"w":"issue","p":"v./n.","d":"to give out officially; one edition of a magazine","c":"常見：問題；議題／進階：發行；核發；（期刊的）一期","s":"The government issued a warning about the coming typhoon.","t":"政府發布了颱風來襲的警報。"},{"w":"labor","p":"n.","d":"the process of giving birth","c":"常見：勞動；勞工／進階：分娩；陣痛","s":"My aunt was in labor for ten hours before the baby was born.","t":"我阿姨陣痛十小時寶寶才出生。"},{"w":"launch","p":"v./n.","d":"to start something new; to introduce a new product","c":"常見：發射；下水／進階：推出；發起","s":"The company will launch its new phone next month.","t":"公司下個月將推出新手機。"},{"w":"lean","p":"adj.","d":"thin and healthy; with little fat","c":"常見：傾斜；倚靠／進階：瘦的；精實的","s":"Chicken breast is a lean meat with lots of protein.","t":"雞胸肉是富含蛋白質的瘦肉。"},{"w":"lecture","p":"v./n.","d":"to criticize someone in a long, serious way","c":"常見：演講；講課／進階：訓斥；說教","s":"My father lectured me for an hour about coming home late.","t":"我晚回家，爸爸訓了我一小時。"},{"w":"manual","p":"adj.","d":"done with the hands","c":"常見：手冊；說明書／進階：手工的；體力的","s":"Robots now do much of the manual work in car factories.","t":"現在汽車工廠大部分的手工作業都由機器人完成。"}]},{"unit":6,"theme":"minister；monitor；peer…","cards":[{"w":"minister","p":"n.","d":"a religious leader in some Christian churches","c":"常見：部長／進階：牧師","s":"The minister married the couple in a small church.","t":"牧師在一間小教堂為這對新人證婚。"},{"w":"monitor","p":"v.","d":"to watch carefully over a period of time","c":"常見：螢幕；顯示器／進階：監控；監測","s":"Nurses monitor the patient's heart rate every hour.","t":"護理師每小時監測病人的心跳。"},{"w":"peer","p":"v.","d":"to look closely because it is hard to see","c":"常見：同儕；同輩／進階：凝視；細看","s":"The old man peered at the small print on the medicine bottle.","t":"老先生瞇著眼細看藥瓶上的小字。"},{"w":"plot","p":"n./v.","d":"a secret plan to do something bad; a small piece of land","c":"常見：情節／進階：陰謀；一小塊地","s":"The police discovered a plot to rob the bank.","t":"警方發現一起搶銀行的陰謀。"},{"w":"polish","p":"v.","d":"to improve a skill or piece of work","c":"常見：擦亮；擦拭／進階：潤飾；精進","s":"She spent a week polishing her speech before the contest.","t":"比賽前她花一週潤飾她的演講稿。"},{"w":"prompt","p":"v./n.","d":"to cause someone to do something; words that help someone remember","c":"常見：及時的；迅速的／進階：促使；提示","s":"The accident prompted the city to put up a traffic light.","t":"這起事故促使市府設置紅綠燈。"},{"w":"reflect","p":"v.","d":"to think carefully about something","c":"常見：反射；反映／進階：反思；深思","s":"Take a moment to reflect on what you learned this year.","t":"花點時間反思你今年學到了什麼。"},{"w":"resolution","p":"n.","d":"a formal decision by a group; how clear an image is","c":"常見：決心／進階：決議；解析度","s":"This camera takes photos at a very high resolution.","t":"這台相機拍的照片解析度很高。"},{"w":"secure","p":"v.","d":"to get something after effort","c":"常見：安全的；牢固的／進階：獲得；取得","s":"Our team secured a place in the final with a last-minute goal.","t":"我們隊靠最後一刻的進球取得決賽資格。"},{"w":"spare","p":"v.","d":"to give time or money; to save someone from something unpleasant","c":"常見：備用的；空閒的／進階：抽出（時間）；饒恕；省去","s":"Could you spare a few minutes to help me with this problem?","t":"你能抽出幾分鐘幫我解決這個問題嗎？"}]},{"unit":7,"theme":"stem；stroke；tense…","cards":[{"w":"stem","p":"v.","d":"to come from something (stem from)","c":"常見：莖；梗／進階：源自；起因於","s":"Many of his health problems stem from a lack of sleep.","t":"他許多健康問題源自睡眠不足。"},{"w":"stroke","p":"v./n.","d":"to touch gently; a single line made with a pen","c":"常見：中風／進階：撫摸；一筆；一劃","s":"She stroked the cat until it fell asleep.","t":"她撫摸著貓直到牠睡著。"},{"w":"tense","p":"n.","d":"the form of a verb that shows time","c":"常見：緊張的；緊繃的／進階：（文法）時態","s":"Use the past tense when you write about last weekend.","t":"寫上週末的事時要用過去式。"},{"w":"vessel","p":"n.","d":"a tube in the body that carries blood; a container for liquid","c":"常見：船；艦／進階：血管；容器","s":"Smoking can damage the blood vessels and cause heart disease.","t":"抽菸會損害血管並引發心臟病。"},{"w":"accommodate","p":"v.","d":"to change to fit someone's needs","c":"常見：容納；提供住宿／進階：遷就；配合","s":"The school tries to accommodate students with special needs.","t":"學校盡量配合有特殊需求的學生。"},{"w":"alien","p":"adj./n.","d":"strange and unfamiliar; a person from another country","c":"常見：外星人／進階：陌生的；外國人","s":"City life felt alien to the boy from the mountains.","t":"對來自山區的男孩來說，都市生活很陌生。"},{"w":"betray","p":"v.","d":"to show a feeling you want to hide","c":"常見：背叛；出賣／進階：流露；洩露","s":"Her shaking hands betrayed how nervous she was.","t":"她顫抖的雙手洩露了她有多緊張。"},{"w":"boom","p":"n./v.","d":"a time of fast growth","c":"常見：隆隆聲；轟鳴／進階：繁榮；激增","s":"There has been a boom in online shopping since 2020.","t":"2020 年以來網購激增。"},{"w":"bound","p":"adj.","d":"going toward a place (bound for)","c":"常見：必定的；一定會／進階：開往…的","s":"This train is bound for Kaohsiung and will stop at every station.","t":"這班火車開往高雄，每站都停。"},{"w":"clinical","p":"adj.","d":"cold and without emotion","c":"常見：臨床的／進階：冷靜客觀的；冷冰冰的","s":"The hotel room was clean but felt clinical, with white walls and no pictures.","t":"飯店房間很乾淨，但白牆沒掛畫，感覺冷冰冰的。"}]},{"unit":8,"theme":"commission；compromise；conduct…","cards":[{"w":"commission","p":"n./v.","d":"money paid for each sale; to ask an artist to make something","c":"常見：委員會／進階：佣金；委託","s":"The city commissioned an artist to paint a large wall in the park.","t":"市政府委託一位藝術家在公園畫大型壁畫。"},{"w":"compromise","p":"v.","d":"to put something in danger; to weaken","c":"常見：妥協；折衷／進階：危及；損害","s":"Using a weak password can compromise the safety of your account.","t":"使用弱密碼會危及帳號安全。"},{"w":"conduct","p":"v.","d":"to carry out; to lead an orchestra; to let heat or electricity pass","c":"常見：行為；舉止／進階：進行；指揮；傳導","s":"The class conducted a survey about students' sleeping habits.","t":"這個班進行了一項學生睡眠習慣的調查。"},{"w":"conviction","p":"n.","d":"a strong belief","c":"常見：定罪；有罪判決／進階：堅定的信念","s":"She spoke with deep conviction about the need to protect the ocean.","t":"她以堅定的信念談論保護海洋的必要。"},{"w":"deliberate","p":"v./adj.","d":"to think carefully before deciding; slow and careful","c":"常見：故意的；蓄意的／進階：仔細考慮；從容謹慎的","s":"The judges deliberated for an hour before choosing the winner.","t":"評審們仔細討論一小時後才選出優勝者。"},{"w":"execute","p":"v.","d":"to kill someone as a legal punishment","c":"常見：執行；實行／進階：處死；處決","s":"In the past, criminals were executed in public.","t":"過去罪犯會被公開處決。"},{"w":"exploit","p":"n.","d":"a brave or exciting act","c":"常見：剝削；利用；開發／進階：英勇事蹟；功績","s":"The old sailor loved telling us about his exploits at sea.","t":"老水手喜歡跟我們講他在海上的英勇事蹟。"},{"w":"fabric","p":"n.","d":"the basic structure of a society or building","c":"常見：布料；織物／進階：結構；構造","s":"Crime can damage the fabric of a community.","t":"犯罪會破壞社區的結構。"},{"w":"faculty","p":"n.","d":"a natural ability of the body or mind","c":"常見：全體教職員；學院／進階：能力；官能","s":"Even at ninety, my grandmother still has all her mental faculties.","t":"即使九十歲了，我奶奶的心智能力仍然健全。"},{"w":"forge","p":"v.","d":"to create a strong relationship; to move forward with effort","c":"常見：偽造／進階：建立（關係）；穩步前進","s":"The two schools forged a close friendship through the exchange program.","t":"兩校透過交換計畫建立了深厚情誼。"}]},{"unit":9,"theme":"foster；grant；gravity…","cards":[{"w":"foster","p":"v.","d":"to help something develop","c":"常見：寄養的；收養／進階：促進；培養","s":"Group projects foster cooperation among students.","t":"小組專題能培養學生之間的合作。"},{"w":"grant","p":"n.","d":"money given by a government or organization for a purpose","c":"常見：給予；准許／進階：補助金；獎助金","s":"She received a government grant to study music in Vienna.","t":"她獲得政府補助赴維也納學音樂。"},{"w":"gravity","p":"n.","d":"seriousness","c":"常見：重力；地心引力／進階：嚴重性；嚴肅","s":"The doctor explained the gravity of my father's illness.","t":"醫生向我們說明父親病情的嚴重性。"},{"w":"gross","p":"adj.","d":"total, before anything is taken away","c":"常見：噁心的／進階：總的；毛的","s":"His gross income is high, but he pays a lot of tax.","t":"他的總收入很高，但要繳很多稅。"},{"w":"mint","p":"n./adj.","d":"a place where coins are made; (in mint condition) like new","c":"常見：薄荷／進階：鑄幣廠；全新的","s":"The old comic book is in mint condition, so it is worth a lot.","t":"這本舊漫畫完好如新，所以很值錢。"},{"w":"mock","p":"adj.","d":"not real; done for practice","c":"常見：嘲笑；嘲弄／進階：模擬的；假的","s":"We have a mock exam next week to prepare for the GSAT.","t":"下週有模擬考，準備學測。"},{"w":"mount","p":"v.","d":"to increase gradually; to organize","c":"常見：登上；騎上／進階：逐漸增加；舉辦","s":"Pressure on the students mounted as the exam got closer.","t":"隨著考試逼近，學生的壓力逐漸增加。"},{"w":"odds","p":"n.","d":"(at odds) disagreeing; (against all odds) despite difficulties","c":"常見：機率；可能性／進階：不和；困難重重","s":"Against all odds, the small team won the championship.","t":"儘管困難重重，這支小隊仍贏得冠軍。"},{"w":"outlet","p":"n.","d":"a way of expressing feelings; a store selling cheap goods","c":"常見：插座／進階：發洩管道；暢貨中心","s":"Playing drums is a good outlet for his energy.","t":"打鼓是他宣洩精力的好管道。"},{"w":"patent","p":"adj.","d":"very obvious","c":"常見：專利（權）；取得專利／進階：明顯的","s":"His excuse was a patent lie; nobody believed him.","t":"他的藉口是明顯的謊言，沒人相信。"}]},{"unit":10,"theme":"pedestrian；premium；radical…","cards":[{"w":"pedestrian","p":"adj.","d":"dull and ordinary","c":"常見：行人／進階：平淡的；乏味的","s":"Critics called the movie's story pedestrian and predictable.","t":"影評說這部電影的故事平淡無奇、毫無驚喜。"},{"w":"premium","p":"adj.","d":"of high quality and expensive","c":"常見：保險費／進階：高級的；優質的","s":"The shop sells premium coffee beans from Ethiopia.","t":"這家店販售衣索比亞的高級咖啡豆。"},{"w":"radical","p":"adj.","d":"very basic and thorough","c":"常見：激進的；激進分子／進階：根本的；徹底的","s":"The internet brought radical changes to the way we shop.","t":"網路徹底改變了我們購物的方式。"},{"w":"rear","p":"v.","d":"to take care of children or animals until they grow up","c":"常見：後方；後部／進階：撫養；飼養","s":"She reared three children on her own.","t":"她獨自撫養三個孩子。"},{"w":"resort","p":"v./n.","d":"to do something because there is no other choice (resort to)","c":"常見：度假勝地／進階：訴諸；手段","s":"We should never resort to violence to solve problems.","t":"我們絕不應該訴諸暴力來解決問題。"},{"w":"shed","p":"v.","d":"to let something fall off; to get rid of","c":"常見：小屋；棚子／進階：脫落；流（淚）；擺脫","s":"Many trees shed their leaves in autumn.","t":"許多樹在秋天落葉。"},{"w":"squash","p":"n.","d":"a kind of vegetable like a pumpkin; an indoor game with rackets","c":"常見：壓扁；擠／進階：南瓜類蔬菜；壁球","s":"My father plays squash with his friends every Friday.","t":"我爸爸每週五和朋友打壁球。"},{"w":"stall","p":"v.","d":"(of an engine) to stop suddenly; to delay","c":"常見：攤位／進階：熄火；拖延","s":"The car stalled in the middle of the road.","t":"車子在路中間熄火了。"},{"w":"stock","p":"n.","d":"shares in a company; liquid made from meat or bones for soup","c":"常見：庫存；存貨／進階：股票；高湯","s":"She invested some of her savings in stocks.","t":"她把部分存款投資股票。"},{"w":"strain","p":"n./v.","d":"a type of virus or plant; to separate liquid from food","c":"常見：拉傷；壓力；負擔／進階：品系；（病毒）株；過濾","s":"Scientists discovered a new strain of the flu virus.","t":"科學家發現一種新的流感病毒株。"}]},{"unit":11,"theme":"striking；sustain；terminal…","cards":[{"w":"striking","p":"adj.","d":"refusing to work as a protest","c":"常見：醒目的；驚人的／進階：罷工的","s":"Striking workers gathered outside the factory gate.","t":"罷工的工人聚集在工廠大門外。"},{"w":"sustain","p":"v.","d":"to suffer an injury or loss","c":"常見：維持；支撐／進階：遭受；蒙受","s":"The driver sustained serious injuries in the crash.","t":"駕駛在車禍中受了重傷。"},{"w":"terminal","p":"adj.","d":"(of an illness) causing death and unable to be cured","c":"常見：航廈；終點站／進階：末期的；致命的","s":"The hospital provides care for patients with terminal illnesses.","t":"這家醫院為末期病患提供照護。"},{"w":"toll","p":"n.","d":"the number of people killed; bad effects","c":"常見：通行費／進階：傷亡人數；損害","s":"Years of hard work took a toll on his health.","t":"多年的辛苦工作損害了他的健康。"},{"w":"yield","p":"v.","d":"to give in; to allow other cars to go first","c":"常見：生產；產生；產量／進階：讓步；屈服；讓路","s":"Drivers must yield to people crossing the street.","t":"駕駛人必須禮讓過馬路的行人。"},{"w":"anchor","p":"n./v.","d":"a person who presents the news on TV; to hold firmly","c":"常見：錨；下錨／進階：主播；穩定","s":"She became the main news anchor at a national TV station.","t":"她成為全國性電視台的主播。"},{"w":"compass","p":"n.","d":"a tool for drawing circles; range","c":"常見：指南針；羅盤／進階：圓規；範圍","s":"Use a compass to draw a circle with a radius of five centimeters.","t":"用圓規畫一個半徑五公分的圓。"},{"w":"console","p":"v.","d":"to comfort someone who is sad","c":"常見：遊戲主機；控制台／進階：安慰","s":"She tried to console her friend after he lost the game.","t":"朋友輸了比賽後她試著安慰他。"},{"w":"hail","p":"v.","d":"to wave to stop a taxi; to praise publicly","c":"常見：冰雹；下冰雹／進階：招呼；歡呼；稱讚","s":"The young doctor was hailed as a hero for saving the passengers.","t":"這位年輕醫師因救了乘客而被譽為英雄。"},{"w":"outgoing","p":"adj.","d":"leaving a job; going out","c":"常見：外向的；友善的／進階：即將離任的；外發的","s":"The outgoing principal gave a speech at her last school assembly.","t":"即將卸任的校長在最後一次朝會致詞。"}]},{"unit":12,"theme":"provincial；rash；spectacle…","cards":[{"w":"provincial","p":"adj.","d":"narrow-minded; not interested in new ideas","c":"常見：省的；地方的／進階：見識狹隘的；鄉氣的","s":"His provincial views changed after he studied abroad.","t":"出國留學後他狹隘的觀念改變了。"},{"w":"rash","p":"adj.","d":"done too quickly without thinking","c":"常見：疹子／進階：輕率的；魯莽的","s":"Don't make a rash decision when you are angry.","t":"生氣時別做草率的決定。"},{"w":"spectacle","p":"n.","d":"(spectacles) glasses","c":"常見：奇觀；壯觀景象／進階：眼鏡","s":"Grandpa can't read without his spectacles.","t":"爺爺沒戴眼鏡就看不了字。"},{"w":"upright","p":"adj.","d":"honest and responsible","c":"常見：直立的；挺直地／進階：正直的","s":"He is an upright man who never cheats anyone.","t":"他是個正直的人，從不欺騙任何人。"},{"w":"utter","p":"adj.","d":"complete; total","c":"常見：說出；發出／進階：完全的；徹底的","s":"The party was an utter failure because nobody came.","t":"派對徹底失敗，因為沒有人來。"},{"w":"ward","p":"v.","d":"to keep something bad away (ward off)","c":"常見：病房／進階：避開；抵擋","s":"People used to hang garlic on doors to ward off evil spirits.","t":"人們以前會在門上掛大蒜驅邪。"},{"w":"warrant","p":"v.","d":"to make something necessary or reasonable","c":"常見：（搜索、逮捕）令／進階：使有正當理由；使成為必要","s":"The small mistake doesn't warrant such a heavy punishment.","t":"這個小錯誤不值得如此重罰。"}]}];
